use governor::{Quota, RateLimiter};
use std::num::NonZeroU32;
let quota = Quota::per_second(NonZeroU32::new(100).unwrap());  // 100/s
let limiter = RateLimiter::keyed(quota);                      // one bucket per key
if limiter.check_key(&user_id).is_ok() { handle(&user_id) }
else { respond_429() }                                        // NotUntil carries retry timing

